import{_ as s}from"./chunks/embed-playground.DUFBb3fy.js";import{_ as t,o as i,c as n,ag as a}from"./chunks/framework.DqVSm8kp.js";const h=JSON.parse('{"title":"Plongements","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/embeddings.md","filePath":"fr/guide/embeddings.md"}'),r={name:"fr/guide/embeddings.md"};function o(l,e,d,u,m,c){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="plongements" tabindex="-1">Plongements <a class="header-anchor" href="#plongements" aria-label="Permalink to &quot;Plongements&quot;">​</a></h1><p>La page Plongements vous permet de generer des embeddings textuels et de comparer visuellement la similarite semantique entre deux textes.</p><p><strong>Element de la barre laterale :</strong> Plongements <strong>Route :</strong> <code>/embeddings</code></p><p><img src="'+s+'" alt="Playground Plongements"></p><h2 id="qu-est-ce-qu-un-embedding" tabindex="-1">Qu&#39;est-ce qu&#39;un embedding ? <a class="header-anchor" href="#qu-est-ce-qu-un-embedding" aria-label="Permalink to &quot;Qu&#39;est-ce qu&#39;un embedding ?&quot;">​</a></h2><p>Un embedding est une liste de nombres (un vecteur) qui represente le sens d&#39;un texte. Des textes ayant des significations proches produisent des vecteurs pointant dans des directions similaires. LLMxRay utilise ce concept pour vous permettre d&#39;explorer la similarite semantique de maniere concrete.</p><h2 id="generer-un-embedding" tabindex="-1">Generer un embedding <a class="header-anchor" href="#generer-un-embedding" aria-label="Permalink to &quot;Generer un embedding&quot;">​</a></h2><ol><li>Selectionnez un <strong>modele d&#39;embedding</strong> dans le menu deroulant. Seuls les modeles ayant des capacites d&#39;embedding apparaissent (par ex., <code>nomic-embed-text</code>, <code>all-minilm</code>).</li><li>Saisissez du texte dans la zone de saisie.</li><li>Cliquez sur <strong>Embed</strong>. Le vecteur resultant est affiche sous forme de graphique a barres.</li></ol><div class="tip custom-block"><p class="custom-block-title">Pas de modele d&#39;embedding ?</p><p>Si aucun modele n&#39;apparait dans le menu deroulant, vous devez en telecharger un :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nomic-embed-text</span></span></code></pre></div></div><h2 id="comparer-deux-textes" tabindex="-1">Comparer deux textes <a class="header-anchor" href="#comparer-deux-textes" aria-label="Permalink to &quot;Comparer deux textes&quot;">​</a></h2><ol><li>Saisissez du texte dans les deux zones de saisie.</li><li>Cliquez sur <strong>Comparer</strong>. Les deux textes sont transformes en embeddings et compares.</li><li>Le <strong>compteur de similarite cosinus</strong> indique la proximite semantique des deux textes : <ul><li><strong>1.0</strong> -- Signification identique</li><li><strong>0.7+</strong> -- Tres similaire</li><li><strong>0.3-0.7</strong> -- Partiellement lies</li><li><strong>&lt; 0.3</strong> -- Sans rapport</li></ul></li></ol><h2 id="cas-d-utilisation" tabindex="-1">Cas d&#39;utilisation <a class="header-anchor" href="#cas-d-utilisation" aria-label="Permalink to &quot;Cas d&#39;utilisation&quot;">​</a></h2><ul><li><strong>Comprendre les embeddings</strong> -- Voir ce que ces nombres representent concretement</li><li><strong>Tester la pertinence RAG</strong> -- Verifier si vos documents correspondront aux requetes des utilisateurs</li><li><strong>Explorer les synonymes</strong> -- Observer comment le modele comprend les relations semantiques</li><li><strong>Pedagogie</strong> -- Ideal pour les cours d&#39;IA/ML sur les representations vectorielles</li></ul><h2 id="astuces" tabindex="-1">Astuces <a class="header-anchor" href="#astuces" aria-label="Permalink to &quot;Astuces&quot;">​</a></h2><ul><li>Differents modeles d&#39;embedding produisent des dimensions de vecteurs et des scores de similarite differents.</li><li>Des textes courts et cibles produisent des comparaisons plus pertinentes que de longs paragraphes.</li><li>Les resultats sont stockes dans la session et peuvent etre consultes ulterieurement.</li></ul>',15)])])}const b=t(r,[["render",o]]);export{h as __pageData,b as default};
